def loopSum : List ℕ → ℕ :=
fun xs =>
  (have acc := 0;
    do
    let r ←
      forIn xs acc fun x r =>
          have acc := r;
          have acc := acc + x;
          do
          pure PUnit.unit
          pure (ForInStep.yield acc)
    have acc : ℕ := r
    pure acc).run

